/* @lc app=leetcode id=3363 lang=kotlin */ class Solution { fun path(g: Array<IntArray>): Int = g.size.let { n -> (1 until n - 1).fold(IntArray(n) { if (it == n - 1) g[0][n - 1] else -1_000_000_000 }) { prev, i -> IntArray(n) { j -> if (j > i) maxOf(prev[j], if (j > 0) prev[j - 1] else -1_000_000_000, if (j < n - 1) prev[j + 1] else -1_000_000_000) + g[i][j] else -1_000_000_000 } }[n - 1] } fun maxCollectedFruits(fruits: Array<IntArray>): Int = fruits.indices.sumOf { fruits[it][it] } + path(fruits) + path(Array(fruits.size) { i -> IntArray(fruits.size) { j -> fruits[j][i] } }) }